    0x7e, 0xc8, 0xdd, 0x9e, 0xe8, 0x8f, 0x87, 0x3d, 0xb0, 0x65, 0x4e, 0xbd,
    0xd0, 0xad, 0xd5, 0xb7, 0x46, 0x2b, 0xf6, 0xa2, 0xad, 0xa1, 0xb5, 0xd7,
    0x6e, 0x57, 0x17, 0x29, 0x25, 0xb5, 0xfd, 0xef, 0x00, 0x23, 0x44, 0x4b,
    0x6a, 0x5d, 0x6b, 0x72, 0xa4, 0xf9, 0x9b, 0xb0, 0xc9, 0x22, 0x51, 0x5d,
    0x75, 0x87, 0xd4, 0x0b, 0x92, 0xd9, 0xdc, 0x2e, 0x39, 0xa1, 0xd8, 0xe5,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x05, 0x0a, 0x0d, 0x13, 0x17, 0x1c,
};

var generated_public_key: packing.PublicKeyBytes = [_]u8{0} ** params.PUBLIC_KEY_BYTES;
var generated_secret_key: packing.SecretKeyBytes = [_]u8{0} ** params.SECRET_KEY_BYTES;
var generated_signature: packing.SignatureBytes = [_]u8{0} ** params.SIGNATURE_BYTES;
var public_digest: [DIGEST_BYTES]u8 = [_]u8{0} ** DIGEST_BYTES;
var secret_digest: [DIGEST_BYTES]u8 = [_]u8{0} ** DIGEST_BYTES;
var signature_digest: [DIGEST_BYTES]u8 = [_]u8{0} ** DIGEST_BYTES;
var running: bool = false;

pub fn vectorsProvisioned() bool {
    return VECTORS_PROVISIONED and provisioningLooksValid();
}

pub fn getStatus() Status {
    if (!vectorsProvisioned()) return .not_provisioned;
    return if (selfTest()) .passed else .failed;
}

pub fn selfTest() bool {
    return run().allPassed();
}

pub fn run() Results {
    if (!vectorsProvisioned()) return emptyResult(.not_provisioned, false);
    if (running) return emptyResult(.failed, true);
    running = true;
    clearWorkspace();
    defer {
        clearWorkspace();
        running = false;
    }

    const keygen_ok = keygen.generateFromSeed(
        &generated_public_key,
        &generated_secret_key,
        &KEYGEN_SEED,
    );
    const public_hash_ok = keygen_ok and keccak.shake256(
        &public_digest,
        &generated_public_key,
    );
    const secret_hash_ok = keygen_ok and keccak.shake256(
        &secret_digest,
        &generated_secret_key,
    );
    const public_exact = public_hash_ok and constantTimeEqual(
        &public_digest,
        &EXPECTED_PUBLIC_KEY_DIGEST,
    );
    const secret_exact = secret_hash_ok and constantTimeEqual(
        &secret_digest,
        &EXPECTED_SECRET_KEY_DIGEST,
    );

    // FIPS 204 deterministic signing uses an all-zero rnd value. The native
    // signDeterministic API supplies that deterministic randomness internally.
    const signing_ok = signing.signDeterministic(
        &generated_signature,
        &SIGGEN_MESSAGE,
        &SIGGEN_CONTEXT,
        &SIGGEN_SECRET_KEY,
    );
    const signature_hash_ok = signing_ok and keccak.shake256(
        &signature_digest,
        &generated_signature,
    );
    const signature_exact = signature_hash_ok and constantTimeEqual(
        &signature_digest,
        &EXPECTED_SIGNATURE_DIGEST,
    );

    const verification_ok = verification.verify(
        &SIGVER_SIGNATURE,
        &SIGVER_MESSAGE,
        &SIGVER_CONTEXT,
        &SIGVER_PUBLIC_KEY,
    );
    const passed = keygen_ok and public_exact and secret_exact and
        signing_ok and signature_exact and verification_ok;

    return .{
        .status = if (passed) .passed else .failed,
        .vectors_provisioned = true,
        .keygen_completed = keygen_ok,
        .public_key_exact = public_exact,
        .secret_key_exact = secret_exact,
        .signing_completed = signing_ok,
        .signature_exact = signature_exact,
        .verification = verification_ok,
    };
}

fn provisioningLooksValid() bool {
    return VECTORS_PROVISIONED and
        !allZero(&KEYGEN_SEED) and
        !allZero(&EXPECTED_PUBLIC_KEY_DIGEST) and
        !allZero(&EXPECTED_SECRET_KEY_DIGEST) and
        !allZero(&EXPECTED_SIGNATURE_DIGEST) and
        SIGGEN_CONTEXT.len <= 255 and SIGVER_CONTEXT.len <= 255;
}

fn emptyResult(status: Status, provisioned: bool) Results {
    return .{
        .status = status,
        .vectors_provisioned = provisioned,
        .keygen_completed = false,
        .public_key_exact = false,
        .secret_key_exact = false,
        .signing_completed = false,
        .signature_exact = false,
        .verification = false,
    };
}

fn allZero(bytes: []const u8) bool {
    var combined: u8 = 0;
    for (bytes) |byte| combined |= byte;
    return combined == 0;
}

fn constantTimeEqual(left: []const u8, right: []const u8) bool {
    if (left.len != right.len) return false;
    var difference: u8 = 0;
    for (left, right) |a, b| difference |= a ^ b;
    return difference == 0;
}

fn clearWorkspace() void {
    @memset(generated_public_key[0..], 0);
    @memset(generated_secret_key[0..], 0);
    @memset(generated_signature[0..], 0);
    @memset(public_digest[0..], 0);
    @memset(secret_digest[0..], 0);
    @memset(signature_digest[0..], 0);
}
